CSS_TEXT = ':root{--bg:#f6f5ff;--bg-soft:#ffffff;--text:#201a3a;--text-muted:#635e7a;--primary:#7c3aed;--primary-2:#ec4899;--accent:#f59e0b;--success:#16a34a;--card-border:rgba(124,58,237,0.15);--shadow:0 10px 30px rgba(124,58,237,0.12);--radius:18px}[data-theme="dark"]{--bg:#0f0b23;--bg-soft:#1a1436;--text:#f2f0ff;--text-muted:#b3aed1;--primary:#a78bfa;--primary-2:#f472b6;--accent:#fbbf24;--success:#4ade80;--card-border:rgba(167,139,250,0.25);--shadow:0 10px 30px rgba(0,0,0,0.4)}*{box-sizing:border-box}body{margin:0;font-family:"Vazirmatn",Tahoma,sans-serif;background:var(--bg);color:var(--text);direction:rtl;transition:background 0.3s ease,color 0.3s ease;min-height:100vh}a{color:inherit;text-decoration:none}.container{max-width:1080px;margin:0 auto;padding:0 20px}.navbar{display:flex;align-items:center;justify-content:space-between;padding:16px 24px;background:var(--bg-soft);box-shadow:var(--shadow);position:sticky;top:0;z-index:50}.brand{display:flex;align-items:center;gap:10px;font-weight:800;font-size:1.4rem;background:linear-gradient(90deg,var(--primary),var(--primary-2));-webkit-background-clip:text;background-clip:text;color:transparent}.brand .logo-dot{width:14px;height:14px;border-radius:50%;background:linear-gradient(135deg,var(--accent),var(--primary-2));box-shadow:0 0 12px var(--accent)}.navbar-actions{display:flex;align-items:center;gap:10px}.nav-hamburger{display:flex;flex-direction:column;justify-content:center;align-items:center;width:42px;height:42px;padding:0;border:1px solid var(--card-border);border-radius:12px;background:var(--bg);cursor:pointer;flex-shrink:0}.nav-hamburger span{display:block;width:20px;height:2px;min-height:2px;border-radius:2px;background:var(--text);margin:3px 0;transition:transform 0.2s ease,opacity 0.2s ease}.nav-hamburger span:first-child{margin-top:0}.nav-hamburger span:last-child{margin-bottom:0}.nav-links a.nav-disabled{opacity:0.45;cursor:not-allowed;position:relative}.nav-links a.nav-disabled::after{content:"🔒";font-size:0.75rem;margin-right:6px}.nav-links a.nav-disabled:hover{background:transparent;color:var(--text-muted)}.nav-links{display:none;flex-direction:column;gap:4px;position:absolute;top:68px;left:16px;right:16px;background:var(--bg-soft);border:1px solid var(--card-border);border-radius:var(--radius);box-shadow:var(--shadow);padding:10px;z-index:60;max-width:320px;margin-inline-start:auto}.nav-links.open{display:flex}.nav-links a{padding:10px 14px;border-radius:12px;font-weight:600;font-size:0.92rem;color:var(--text-muted);text-align:right}.nav-links a:hover,.nav-links a.active{background:linear-gradient(90deg,var(--primary),var(--primary-2));color:#fff}.nav-overlay{display:none;position:fixed;inset:0;background:rgba(0,0,0,0.35);z-index:45;pointer-events:none}.nav-overlay.open{display:block;pointer-events:auto}.theme-toggle{border:none;cursor:pointer;border-radius:999px;padding:8px 16px;font-weight:700;background:var(--bg);color:var(--text);border:1px solid var(--card-border)}.hero{text-align:center;padding:60px 20px 40px}.hero h1{font-size:2.2rem;margin-bottom:10px;background:linear-gradient(90deg,var(--primary),var(--primary-2),var(--accent));-webkit-background-clip:text;background-clip:text;color:transparent}.hero p{color:var(--text-muted);font-size:1.05rem;max-width:640px;margin:0 auto}.card{background:var(--bg-soft);border:1px solid var(--card-border);border-radius:var(--radius);box-shadow:var(--shadow);padding:28px;margin:20px auto}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}@media (max-width:640px){.form-grid{grid-template-columns:1fr}}.field{display:flex;flex-direction:column;gap:6px}label{font-weight:600;font-size:0.9rem;color:var(--text-muted)}input,select,textarea{padding:12px 14px;border-radius:12px;border:1px solid var(--card-border);background:var(--bg);color:var(--text);font-family:inherit;font-size:0.95rem}input:focus,select:focus,textarea:focus{outline:none;border-color:var(--primary)}.btn{display:inline-block;cursor:pointer;border:none;padding:13px 26px;border-radius:999px;font-weight:700;font-size:0.98rem;background:linear-gradient(90deg,var(--primary),var(--primary-2));color:#fff;transition:transform 0.15s ease,box-shadow 0.15s ease}.btn:hover{transform:translateY(-2px);box-shadow:0 8px 18px rgba(124,58,237,0.35)}.btn.secondary{background:transparent;border:2px solid var(--primary);color:var(--primary)}.btn.gold{background:linear-gradient(90deg,var(--accent),var(--primary-2))}.btn.block{width:100%;text-align:center}.day-card{border:1px solid var(--card-border);border-radius:14px;padding:16px 18px;margin-bottom:12px;background:var(--bg)}.day-card .day-title{font-weight:800;color:var(--primary);margin-bottom:8px;display:flex;justify-content:space-between;align-items:center}.day-tag{font-size:0.75rem;padding:3px 10px;border-radius:999px;background:linear-gradient(90deg,var(--accent),var(--primary-2));color:#fff}.item-row{display:flex;justify-content:space-between;padding:6px 0;border-bottom:1px dashed var(--card-border);font-size:0.9rem}.item-row:last-child{border-bottom:none}.item-row .subject-name{font-weight:700}.item-row .minutes{color:var(--text-muted);font-size:0.8rem}.pricing-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:18px}.price-card{background:var(--bg-soft);border:1px solid var(--card-border);border-radius:var(--radius);padding:24px 20px;text-align:center;box-shadow:var(--shadow);display:flex;flex-direction:column;gap:10px}.price-card .price{font-size:1.5rem;font-weight:800;background:linear-gradient(90deg,var(--primary),var(--primary-2));-webkit-background-clip:text;background-clip:text;color:transparent}.leader-row{display:flex;align-items:center;justify-content:space-between;padding:14px 18px;border-radius:14px;margin-bottom:10px;background:var(--bg-soft);border:1px solid var(--card-border)}.leader-row.top-1{border:2px solid var(--accent)}.leader-row.top-2{border:2px solid #c0c0c0}.leader-row.top-3{border:2px solid #cd7f32}.rank-badge{width:34px;height:34px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-weight:800;background:var(--bg);border:1px solid var(--card-border)}.option-btn{display:block;width:100%;text-align:right;padding:12px 16px;margin-bottom:8px;border-radius:12px;border:1px solid var(--card-border);background:var(--bg);color:var(--text);cursor:pointer;font-family:inherit;font-size:0.92rem}.option-btn.selected{border-color:var(--primary);background:rgba(124,58,237,0.1)}.option-btn.correct{border-color:var(--success);background:rgba(22,163,74,0.12)}.option-btn.wrong{border-color:#ef4444;background:rgba(239,68,68,0.12)}footer{text-align:center;padding:24px;color:var(--text-muted);font-size:0.85rem}.badge-note{font-size:0.8rem;color:var(--text-muted);background:rgba(124,58,237,0.08);border-radius:10px;padding:8px 12px;margin-top:10px}.alert{padding:12px 16px;border-radius:12px;margin:12px 0;font-size:0.9rem}.alert.success{background:rgba(22,163,74,0.12);color:var(--success)}.alert.error{background:rgba(239,68,68,0.12);color:#ef4444}.brand-logo{height:40px;width:40px;object-fit:cover;border-radius:10px}#bg3d-canvas{position:fixed;inset:0;width:100%;height:100%;z-index:-1;pointer-events:none;opacity:0.55}[data-theme="dark"] #bg3d-canvas{opacity:0.75}.hero{position:relative;overflow:hidden}.hero::before{content:"";position:absolute;inset:0;background-image:url(\'/logo.jpg\');background-repeat:no-repeat;background-position:center;background-size:260px;opacity:0.05;filter:blur(1px);pointer-events:none;z-index:0}.hero > *{position:relative;z-index:1}.brand-logo-watermark{width:120px;height:120px;border-radius:50%;object-fit:cover;box-shadow:0 0 40px rgba(124,58,237,0.45);margin-bottom:14px;animation:floatLogo 4s ease-in-out infinite}@keyframes floatLogo{0%,100%{transform:translateY(0)}50%{transform:translateY(-10px)}}footer{position:relative}footer .footer-logo{width:34px;height:34px;border-radius:50%;vertical-align:middle;margin-left:8px;object-fit:cover}'

THEME_JS = "(function () {\n  const saved = localStorage.getItem(\"noortika-theme\") || \"light\";\n  document.documentElement.setAttribute(\"data-theme\", saved);\n\n  window.addEventListener(\"DOMContentLoaded\", () => {\n    const btn = document.getElementById(\"theme-toggle-btn\");\n    updateBtnLabel(btn, saved);\n    if (btn) {\n      btn.addEventListener(\"click\", () => {\n        const current = document.documentElement.getAttribute(\"data-theme\");\n        const next = current === \"dark\" ? \"light\" : \"dark\";\n        document.documentElement.setAttribute(\"data-theme\", next);\n        localStorage.setItem(\"noortika-theme\", next);\n        updateBtnLabel(btn, next);\n      });\n    }\n  });\n\n  function updateBtnLabel(btn, theme) {\n    if (!btn) return;\n    btn.textContent = theme === \"dark\" ? \"☀️ حالت روز\" : \"🌙 حالت شب\";\n  }\n})();\n"

MAIN_JS = 'const API_BASE = "";\nfunction getUserId() {\n  return localStorage.getItem("noortika-user-id");\n}\nfunction setUserId(id) {\n  localStorage.setItem("noortika-user-id", id);\n}\nfunction requireUser() {\n  const id = getUserId();\n  if (!id) {\n    try { localStorage.setItem("noortika-return-path", window.location.pathname); } catch (e) {}\n    window.location.href = "/?auth_required=1";\n    return null;\n  }\n  return id;\n}\nasync function apiPost(path, body) {\n  const res = await fetch(API_BASE + path, {\n    method: "POST",\n    headers: { "Content-Type": "application/json" },\n    body: JSON.stringify(body),\n  });\n  if (!res.ok) {\n    const err = await res.json().catch(() => ({ detail: "خطای ناشناخته" }));\n    throw new Error(err.detail || "خطا در ارتباط با سرور");\n  }\n  return res.json();\n}\nasync function apiGet(path) {\n  const res = await fetch(API_BASE + path);\n  if (!res.ok) {\n    const err = await res.json().catch(() => ({ detail: "خطای ناشناخته" }));\n    throw new Error(err.detail || "خطا در ارتباط با سرور");\n  }\n  return res.json();\n}\ndocument.addEventListener("DOMContentLoaded", () => {\n  const path = window.location.pathname;\n  document.querySelectorAll(".nav-links a").forEach((a) => {\n    if (a.getAttribute("href") === path) a.classList.add("active");\n  });\n});\ndocument.addEventListener("DOMContentLoaded", () => {\n  const loggedIn = !!getUserId();\n  document.querySelectorAll(".nav-links a[data-gated]").forEach((a) => {\n    if (loggedIn) return;\n    a.classList.add("nav-disabled");\n    a.addEventListener("click", (e) => {\n      e.preventDefault();\n      try { localStorage.setItem("noortika-return-path", a.getAttribute("href")); } catch (err) {}\n      window.location.href = "/?auth_required=1";\n    });\n  });\n});\ndocument.addEventListener("DOMContentLoaded", () => {\n  const hamburger = document.getElementById("nav-hamburger-btn");\n  const menu = document.getElementById("nav-links-menu");\n  const overlay = document.getElementById("nav-overlay");\n  if (!hamburger || !menu) return;\n  function closeMenu() {\n    menu.classList.remove("open");\n    hamburger.setAttribute("aria-expanded", "false");\n    if (overlay) overlay.classList.remove("open");\n  }\n  function toggleMenu() {\n    const isOpen = menu.classList.toggle("open");\n    hamburger.setAttribute("aria-expanded", isOpen ? "true" : "false");\n    if (overlay) overlay.classList.toggle("open", isOpen);\n  }\n  hamburger.addEventListener("click", (e) => { e.stopPropagation(); toggleMenu(); });\n  if (overlay) overlay.addEventListener("click", closeMenu);\n  menu.querySelectorAll("a").forEach((a) => a.addEventListener("click", closeMenu));\n  document.addEventListener("click", (e) => {\n    if (!menu.classList.contains("open")) return;\n    if (menu.contains(e.target) || hamburger.contains(e.target)) return;\n    closeMenu();\n  });\n  document.addEventListener("keydown", (e) => {\n    if (e.key === "Escape") closeMenu();\n  });\n  window.addEventListener("pageshow", closeMenu);\n});\ndocument.addEventListener("DOMContentLoaded", () => {\n  function showTopBanner(message, kind) {\n    let banner = document.getElementById("noortika-top-banner");\n    if (!banner) {\n      banner = document.createElement("div");\n      banner.id = "noortika-top-banner";\n      banner.style.position = "fixed";\n      banner.style.top = "0";\n      banner.style.left = "0";\n      banner.style.right = "0";\n      banner.style.zIndex = "9999";\n      banner.style.textAlign = "center";\n      banner.style.padding = "12px 16px";\n      banner.style.fontWeight = "700";\n      banner.style.fontFamily = "Vazirmatn, sans-serif";\n      banner.style.boxShadow = "0 2px 10px rgba(0,0,0,0.15)";\n      document.body.appendChild(banner);\n    }\n    banner.style.background = kind === "error" ? "#fdecea" : "#e6f4ea";\n    banner.style.color = kind === "error" ? "#b3261e" : "#1e7a34";\n    banner.textContent = message;\n    banner.style.display = "block";\n    clearTimeout(banner._hideTimer);\n    banner._hideTimer = setTimeout(() => {\n      banner.style.display = "none";\n    }, 4000);\n  }\n  const registerLink = document.querySelector(\'.nav-links a[href="/"]\');\n  if (registerLink && registerLink.textContent.trim() === "ثبت\\u200cنام") {\n    registerLink.addEventListener("click", (e) => {\n      if (getUserId()) {\n        e.preventDefault();\n        showTopBanner("شما قبلاً وارد شده\u200cاید.", "success");\n      }\n    });\n  }\n});'

PLAN_JS = 'let customLessons = [];\nlet lastChatPlan = null;\ndocument.addEventListener("DOMContentLoaded", async () => {\n  const userId = requireUser();\n  if (!userId) return;\n  initJalaliPickers();\n  try {\n    const res = await apiGet(`/api/plans/latest/${userId}`);\n    if (res.plan && !res.plan.schedule?.[0]?.date) {\n      renderPlan(res.plan);\n    }\n  } catch (e) {\n    /* بدون برنامه قبلی، مشکلی نیست */\n  }\n  document.getElementById("add-lesson-btn").addEventListener("click", () => {\n    const name = document.getElementById("custom_lesson_name").value.trim();\n    const topicsRaw = document.getElementById("custom_lesson_topics").value.trim();\n    if (!name) return;\n    const topics = topicsRaw ? topicsRaw.split(",").map((t) => t.trim()).filter(Boolean) : [];\n    customLessons.push({ name, topics });\n    document.getElementById("custom_lesson_name").value = "";\n    document.getElementById("custom_lesson_topics").value = "";\n    renderCustomLessons();\n  });\n  document.getElementById("generate-btn").addEventListener("click", async () => {\n    const alertBox = document.getElementById("alert-box");\n    alertBox.innerHTML = `<div class="alert success">در حال ساخت برنامه توسط هوش مصنوعی نورتیکا...</div>`;\n    try {\n      const payload = {\n        user_id: parseInt(userId),\n        plan_type: "week",\n        custom_lessons: customLessons,\n      };\n      const data = await apiPost("/api/plans/generate", payload);\n      alertBox.innerHTML = `<div class="alert success">برنامه شما با موفقیت ساخته شد!</div>`;\n      renderPlan(data.plan);\n    } catch (err) {\n      alertBox.innerHTML = `<div class="alert error">${err.message}</div>`;\n    }\n  });\n  document.getElementById("chat-send-btn").addEventListener("click", sendChatPlanRequest);\n  document.getElementById("log-btn").addEventListener("click", async () => {\n    const hours = parseFloat(document.getElementById("log_hours").value);\n    if (!hours || hours <= 0) return;\n    try {\n      await apiPost("/api/study/log", {\n        user_id: parseInt(userId),\n        hours,\n        subject: document.getElementById("log_subject").value,\n      });\n      const msg = document.getElementById("log-msg");\n      msg.style.display = "inline-block";\n      msg.textContent = "✅ ساعت مطالعه با موفقیت ثبت شد.";\n      document.getElementById("log_hours").value = "";\n      document.getElementById("log_subject").value = "";\n      setBrainFill(hours);\n    } catch (err) {\n      alert(err.message);\n    }\n  });\n  document.getElementById("download-pdf-btn").addEventListener("click", downloadPlanPdf);\n});\nfunction renderCustomLessons() {\n  const container = document.getElementById("custom-lessons-list");\n  container.innerHTML = customLessons\n    .map((l, i) => `<span class="day-tag" style="display:inline-block;margin:4px;">${l.name} ✕</span>`)\n    .join("");\n  container.querySelectorAll("span").forEach((el, i) => {\n    el.style.cursor = "pointer";\n    el.addEventListener("click", () => {\n      customLessons.splice(i, 1);\n      renderCustomLessons();\n    });\n  });\n}\nasync function sendChatPlanRequest() {\n  const userId = getUserId();\n  const message = document.getElementById("chat_message").value.trim();\n  const alertBox = document.getElementById("chat-alert-box");\n  if (!message) {\n    alertBox.innerHTML = `<div class="alert error">لطفاً پیامت را بنویس.</div>`;\n    return;\n  }\n  const days = Array.from(document.querySelectorAll(".weekday-cb:checked")).map((cb) => cb.value);\n  const startDate = document.getElementById("plan_start_date").value;\n  const endDate = document.getElementById("plan_end_date").value;\n  appendChatBubble(message, "user");\n  document.getElementById("chat_message").value = "";\n  alertBox.innerHTML = `<div class="alert success">هوش مصنوعی نورتیکا در حال ساخت برنامه است...</div>`;\n  try {\n    const data = await apiPost("/api/chat-planner/generate", {\n      user_id: parseInt(userId),\n      message,\n      days_of_week: days,\n      start_date: startDate,\n      end_date: endDate,\n    });\n    alertBox.innerHTML = "";\n    lastChatPlan = data.plan;\n    appendChatBubble(data.plan.analysis, "ai");\n    renderSubjectChart(data.plan.subject_distribution);\n    renderGrowthTable(data.plan.growth_table);\n    renderDatedSchedule(data.plan);\n    document.getElementById("pdf-card").style.display = "block";\n    document.getElementById("schedule-container").scrollIntoView({ behavior: "smooth" });\n  } catch (err) {\n    alertBox.innerHTML = `<div class="alert error">${err.message}</div>`;\n  }\n}\nfunction appendChatBubble(text, who) {\n  const history = document.getElementById("chat-history");\n  const bubble = document.createElement("div");\n  bubble.style.margin = "8px 0";\n  bubble.style.padding = "10px 14px";\n  bubble.style.borderRadius = "14px";\n  bubble.style.maxWidth = "90%";\n  bubble.style.fontSize = "0.9rem";\n  bubble.style.lineHeight = "1.7";\n  if (who === "user") {\n    bubble.style.background = "linear-gradient(90deg, var(--primary), var(--primary-2))";\n    bubble.style.color = "#fff";\n    bubble.style.marginRight = "auto";\n    bubble.style.marginLeft = "0";\n  } else {\n    bubble.style.background = "var(--bg)";\n    bubble.style.border = "1px solid var(--card-border)";\n    bubble.style.marginLeft = "auto";\n    bubble.style.marginRight = "0";\n  }\n  bubble.textContent = text;\n  history.appendChild(bubble);\n}\nlet subjectChartInstance = null;\nfunction renderSubjectChart(distribution) {\n  const chartCard = document.getElementById("chart-card");\n  if (!distribution || distribution.length === 0) {\n    chartCard.style.display = "none";\n    return;\n  }\n  chartCard.style.display = "block";\n  const ctx = document.getElementById("subject-pie-chart").getContext("2d");\n  const colors = ["#7c3aed", "#ec4899", "#f59e0b", "#16a34a", "#0ea5e9", "#f472b6", "#a78bfa"];\n  if (subjectChartInstance) subjectChartInstance.destroy();\n  subjectChartInstance = new Chart(ctx, {\n    type: "pie",\n    data: {\n      labels: distribution.map((d) => d.subject),\n      datasets: [{\n        data: distribution.map((d) => d.percent),\n        backgroundColor: distribution.map((_, i) => colors[i % colors.length]),\n      }],\n    },\n    options: { plugins: { legend: { position: "bottom" } } },\n  });\n}\nfunction renderGrowthTable(growth) {\n  const card = document.getElementById("growth-card");\n  const container = document.getElementById("growth-table-container");\n  if (!growth || growth.length === 0) {\n    card.style.display = "none";\n    return;\n  }\n  card.style.display = "block";\n  const rows = growth\n    .map(\n      (g) => `\n    <div class="item-row">\n      <span class="subject-name">هفته ${g.week} — ${g.note || ""}</span>\n      <span class="minutes">${g.expected_mastery_percent}٪ تسلط</span>\n    </div>`\n    )\n    .join("");\n  container.innerHTML = rows;\n}\nfunction renderDatedSchedule(plan) {\n  const container = document.getElementById("schedule-container");\n  const header = `\n    <div class="card">\n      <h3>برنامه ${plan.start_date} تا ${plan.end_date}</h3>\n      <p style="color:var(--text-muted);font-size:0.9rem;">\n        پایه ${plan.grade} · رشته ${plan.field} · دروس: ${plan.focus_subjects.join("، ")}\n      </p>\n    </div>\n  `;\n  const days = plan.schedule\n    .map((day) => {\n      const items = day.items\n        .map(\n          (it) => `\n        <div class="item-row">\n          <span class="subject-name">${it.subject} — ${it.focus}</span>\n          <span class="minutes">${it.minutes} دقیقه</span>\n        </div>`\n        )\n        .join("");\n      return `\n        <div class="day-card">\n          <div class="day-title">\n            <span>${day.date} (${day.day_name})</span>\n            <span class="day-tag">${day.type}</span>\n          </div>\n          ${items}\n        </div>`;\n    })\n    .join("");\n  container.innerHTML = header + `<div class="card">${days}</div>`;\n}\nasync function downloadPlanPdf() {\n  if (!lastChatPlan) return;\n  try {\n    const res = await fetch("/api/chat-planner/pdf", {\n      method: "POST",\n      headers: { "Content-Type": "application/json" },\n      body: JSON.stringify({ plan: lastChatPlan }),\n    });\n    if (!res.ok) throw new Error("خطا در ساخت PDF");\n    const blob = await res.blob();\n    const url = window.URL.createObjectURL(blob);\n    const a = document.createElement("a");\n    a.href = url;\n    a.download = "noortika-plan.pdf";\n    document.body.appendChild(a);\n    a.click();\n    a.remove();\n    window.URL.revokeObjectURL(url);\n  } catch (err) {\n    alert(err.message);\n  }\n}\nfunction renderPlan(plan) {\n  if (plan.ai_advice) {\n    document.getElementById("advice-card").style.display = "block";\n    document.getElementById("advice-text").textContent = plan.ai_advice;\n  }\n  const container = document.getElementById("schedule-container");\n  const header = `\n    <div class="card">\n      <h3>برنامه ${planTypeLabel(plan.plan_type)} — سطح جزئیات: ${plan.detail_level}</h3>\n      <p style="color:var(--text-muted);font-size:0.9rem;">\n        پایه ${plan.grade} · رشته ${plan.field} ${plan.target_major ? "· هدف: " + plan.target_major : ""}\n      </p>\n    </div>\n  `;\n  const days = plan.schedule\n    .map((day) => {\n      const items = day.items\n        .map(\n          (it) => `\n        <div class="item-row">\n          <span class="subject-name">${it.subject} — ${it.focus}</span>\n          <span class="minutes">${it.minutes} دقیقه</span>\n        </div>`\n        )\n        .join("");\n      return `\n        <div class="day-card">\n          <div class="day-title">\n            <span>روز ${day.day}</span>\n            <span class="day-tag">${day.type}</span>\n          </div>\n          ${items}\n        </div>`;\n    })\n    .join("");\n  container.innerHTML = header + `<div class="card">${days}</div>`;\n}\nfunction planTypeLabel(type) {\n  const map = { week: "هفتگی", month: "ماهانه", six_month: "شش\u200cماهه", year: "یک\u200cساله" };\n  return map[type] || type;\n}\n// ---------------------------------------------------------------------\n// تبدیل تاریخ میلادی/شمسی (بدون نیاز به کتابخانه خارجی) و انتخاب\u200cگر تاریخ شمسی\n// ---------------------------------------------------------------------\nconst JALALI_MONTHS = ["فروردین", "اردیبهشت", "خرداد", "تیر", "مرداد", "شهریور", "مهر", "آبان", "آذر", "دی", "بهمن", "اسفند"];\nfunction gregorianToJalali(gy, gm, gd) {\n  const g_d_m = [0, 31, 59, 90, 120, 151, 181, 212, 243, 273, 304, 334];\n  let jy = gy <= 1600 ? 0 : 979;\n  gy -= gy <= 1600 ? 621 : 1600;\n  const gy2 = gm > 2 ? gy + 1 : gy;\n  let days = 365 * gy + Math.floor((gy2 + 3) / 4) - Math.floor((gy2 + 99) / 100) +\n    Math.floor((gy2 + 399) / 400) - 80 + gd + g_d_m[gm - 1];\n  jy += 33 * Math.floor(days / 12053);\n  days %= 12053;\n  jy += 4 * Math.floor(days / 1461);\n  days %= 1461;\n  if (days > 365) {\n    jy += Math.floor((days - 1) / 365);\n    days = (days - 1) % 365;\n  }\n  const jm = days < 186 ? 1 + Math.floor(days / 31) : 7 + Math.floor((days - 186) / 30);\n  const jd = 1 + (days < 186 ? days % 31 : (days - 186) % 30);\n  return [jy, jm, jd];\n}\nfunction jalaliToGregorian(jy, jm, jd) {\n  let gy = jy <= 979 ? 621 : 1600;\n  jy -= jy <= 979 ? 0 : 979;\n  let days = 365 * jy + Math.floor(jy / 33) * 8 + Math.floor(((jy % 33) + 3) / 4) +\n    78 + jd + (jm < 7 ? (jm - 1) * 31 : (jm - 7) * 30 + 186);\n  gy += 400 * Math.floor(days / 146097);\n  days %= 146097;\n  if (days > 36524) {\n    gy += 100 * Math.floor(--days / 36524);\n    days %= 36524;\n    if (days >= 365) days++;\n  }\n  gy += 4 * Math.floor(days / 1461);\n  days %= 1461;\n  gy += Math.floor((days - 1) / 365);\n  if (days > 365) days = (days - 1) % 365;\n  let gd = days + 1;\n  const sal_a = [0, 31, ((gy % 4 === 0 && gy % 100 !== 0) || gy % 400 === 0) ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];\n  let gm = 0;\n  for (gm = 1; gm <= 12 && gd > sal_a[gm]; gm++) gd -= sal_a[gm];\n  return [gy, gm, gd];\n}\nfunction jalaliMonthLength(jy, jm) {\n  if (jm <= 6) return 31;\n  if (jm <= 11) return 30;\n  // اسفند: کبیسه یا نه (تقریب رایج و کافی برای این کاربرد)\n  const isLeap = ((jy % 33) % 4 === 1) || ((jy % 33) === 0);\n  return isLeap ? 30 : 29;\n}\nfunction pad2(n) {\n  return String(n).padStart(2, "0");\n}\nfunction initJalaliPickers() {\n  const today = new Date();\n  const [ty, tm, td] = gregorianToJalali(today.getFullYear(), today.getMonth() + 1, today.getDate());\n  setupOnePicker("start_jy", "start_jm", "start_jd", "plan_start_date", ty, tm, td);\n  setupOnePicker("end_jy", "end_jm", "end_jd", "plan_end_date", ty, tm, td);\n}\nfunction setupOnePicker(yId, mId, dId, hiddenId, defY, defM, defD) {\n  const ySelect = document.getElementById(yId);\n  const mSelect = document.getElementById(mId);\n  const dSelect = document.getElementById(dId);\n  const hidden = document.getElementById(hiddenId);\n  ySelect.innerHTML = "";\n  for (let y = defY - 1; y <= defY + 2; y++) {\n    const opt = document.createElement("option");\n    opt.value = y;\n    opt.textContent = y;\n    if (y === defY) opt.selected = true;\n    ySelect.appendChild(opt);\n  }\n  mSelect.innerHTML = JALALI_MONTHS\n    .map((name, i) => `<option value="${i + 1}" ${i + 1 === defM ? "selected" : ""}>${name}</option>`)\n    .join("");\n  function rebuildDays() {\n    const jy = parseInt(ySelect.value);\n    const jm = parseInt(mSelect.value);\n    const maxDay = jalaliMonthLength(jy, jm);\n    const prevDay = Math.min(parseInt(dSelect.value) || defD, maxDay);\n    dSelect.innerHTML = "";\n    for (let d = 1; d <= maxDay; d++) {\n      const opt = document.createElement("option");\n      opt.value = d;\n      opt.textContent = d;\n      if (d === prevDay) opt.selected = true;\n      dSelect.appendChild(opt);\n    }\n    updateHidden();\n  }\n  function updateHidden() {\n    const jy = parseInt(ySelect.value);\n    const jm = parseInt(mSelect.value);\n    const jd = parseInt(dSelect.value);\n    const [gy, gm, gd] = jalaliToGregorian(jy, jm, jd);\n    hidden.value = `${gy}-${pad2(gm)}-${pad2(gd)}`;\n  }\n  rebuildDays();\n  for (let d = 1; d <= jalaliMonthLength(defY, defM); d++) {\n    if (d === defD) continue;\n  }\n  dSelect.value = defD;\n  updateHidden();\n  ySelect.addEventListener("change", rebuildDays);\n  mSelect.addEventListener("change", rebuildDays);\n  dSelect.addEventListener("change", updateHidden);\n}\n// ---------------------------------------------------------------------\n// انیمیشن پر شدن مغز بر اساس ساعت مطالعه ثبت\u200cشده\n// ---------------------------------------------------------------------\nfunction setBrainFill(hours) {\n  const percent = Math.max(0, Math.min(100, Math.round(hours * 10)));\n  const mask = document.getElementById("brain-fill-mask");\n  const label = document.getElementById("brain-percent-label");\n  if (!mask || !label) return;\n  mask.style.height = percent + "%";\n  label.textContent = percent + "٪ پر شده";\n}'

EXAM_JS = 'let currentQuiz = null;\nlet userAnswers = [];\ndocument.addEventListener("DOMContentLoaded", async () => {\n  const userId = requireUser();\n  if (!userId) return;\n  try {\n    const user = await apiGet(`/api/users/${userId}`);\n    document.getElementById("exam_grade").value = user.grade;\n    document.getElementById("exam_field").value = user.field;\n    await loadSubjects();\n  } catch (e) {\n    console.error(e);\n  }\n  document.getElementById("exam_grade").addEventListener("change", loadSubjects);\n  document.getElementById("exam_field").addEventListener("change", loadSubjects);\n  document.getElementById("exam_subject").addEventListener("change", updateLessonOptions);\n  document.getElementById("start-exam-btn").addEventListener("click", startExam);\n});\nlet subjectsCache = [];\nasync function loadSubjects() {\n  const grade = document.getElementById("exam_grade").value;\n  const field = document.getElementById("exam_field").value;\n  try {\n    const res = await apiGet(`/api/plans/subjects?grade=${encodeURIComponent(grade)}&field=${encodeURIComponent(field)}`);\n    subjectsCache = res.subjects || [];\n    const select = document.getElementById("exam_subject");\n    select.innerHTML = subjectsCache.map((s) => `<option value="${s.name}">${s.name}</option>`).join("");\n    updateLessonOptions();\n  } catch (e) {\n    console.error(e);\n  }\n}\nfunction updateLessonOptions() {\n  const subjectName = document.getElementById("exam_subject").value;\n  const subject = subjectsCache.find((s) => s.name === subjectName);\n  const lessonSelect = document.getElementById("exam_lesson");\n  const topics = (subject && subject.topics) || [];\n  lessonSelect.innerHTML =\n    `<option value="">همه فصل\u200cها</option>` +\n    topics.map((t) => `<option value="${t}">${t}</option>`).join("");\n}\nasync function startExam() {\n  const alertBox = document.getElementById("alert-box");\n  alertBox.innerHTML = `<div class="alert success">در حال طراحی سوالات توسط هوش مصنوعی...</div>`;\n  document.getElementById("result-card").style.display = "none";\n  document.getElementById("wrong-analysis-container").innerHTML = "";\n  const payload = {\n    user_id: parseInt(getUserId()),\n    subject: document.getElementById("exam_subject").value,\n    lesson: document.getElementById("exam_lesson").value,\n    grade: document.getElementById("exam_grade").value,\n    question_count: parseInt(document.getElementById("exam_count").value),\n    difficulty: document.getElementById("exam_difficulty").value,\n    question_type: document.getElementById("exam_type").value,\n  };\n  try {\n    const data = await apiPost("/api/exams/generate", payload);\n    currentQuiz = data.quiz;\n    userAnswers = new Array(currentQuiz.questions.length).fill(currentQuiz.question_type === "تشریحی" ? "" : null);\n    alertBox.innerHTML = currentQuiz.quality_note\n      ? `<div class="alert" style="background:rgba(245,158,11,.12);border:1px solid #f59e0b;color:#f59e0b;">${currentQuiz.quality_note}</div>`\n      : "";\n    renderQuiz();\n  } catch (err) {\n    alertBox.innerHTML = `<div class="alert error">${err.message}</div>`;\n  }\n}\nfunction renderQuiz() {\n  const container = document.getElementById("quiz-container");\n  if (currentQuiz.question_type === "تشریحی") {\n    const html = currentQuiz.questions\n      .map(\n        (q, qi) => `\n    <div class="card">\n      <h4>سوال ${qi + 1} از ${currentQuiz.questions.length} (تشریحی)</h4>\n      <p>${q.question}</p>\n      <textarea data-qi="${qi}" class="essay-answer" rows="4" style="width:100%;padding:12px;border-radius:12px;border:1px solid var(--card-border);background:var(--bg);color:var(--text);font-family:inherit;" placeholder="پاسخ خود را اینجا تایپ کنید..."></textarea>\n    </div>`\n      )\n      .join("");\n    container.innerHTML =\n      html + `<button id="submit-exam-btn" class="btn block" style="margin:20px 0;">پایان آزمون و مشاهده تحلیل</button>`;\n    container.querySelectorAll(".essay-answer").forEach((ta) => {\n      ta.addEventListener("input", () => {\n        userAnswers[parseInt(ta.dataset.qi)] = ta.value;\n      });\n    });\n    document.getElementById("submit-exam-btn").addEventListener("click", submitEssayExam);\n    return;\n  }\n  const html = currentQuiz.questions\n    .map(\n      (q, qi) => `\n    <div class="card">\n      <h4>سوال ${qi + 1} از ${currentQuiz.questions.length}</h4>\n      <p>${q.question}</p>\n      <div class="options" data-qi="${qi}">\n        ${q.options\n          .map(\n            (opt, oi) => `<button type="button" class="option-btn" data-qi="${qi}" data-oi="${oi}">${opt}</button>`\n          )\n          .join("")}\n      </div>\n    </div>`\n    )\n    .join("");\n  container.innerHTML =\n    html + `<button id="submit-exam-btn" class="btn block" style="margin:20px 0;">پایان آزمون و مشاهده نتیجه</button>`;\n  container.querySelectorAll(".option-btn").forEach((btn) => {\n    btn.addEventListener("click", () => {\n      const qi = parseInt(btn.dataset.qi);\n      const oi = parseInt(btn.dataset.oi);\n      userAnswers[qi] = oi;\n      document\n        .querySelectorAll(`.option-btn[data-qi="${qi}"]`)\n        .forEach((b) => b.classList.remove("selected"));\n      btn.classList.add("selected");\n    });\n  });\n  document.getElementById("submit-exam-btn").addEventListener("click", submitExam);\n}\nasync function submitExam() {\n  const correctAnswers = currentQuiz.questions.map((q) => q.correct_index);\n  document.querySelectorAll(".options").forEach((optDiv) => {\n    const qi = parseInt(optDiv.dataset.qi);\n    const correctIdx = correctAnswers[qi];\n    optDiv.querySelectorAll(".option-btn").forEach((btn) => {\n      const oi = parseInt(btn.dataset.oi);\n      if (oi === correctIdx) btn.classList.add("correct");\n      else if (oi === userAnswers[qi] && oi !== correctIdx) btn.classList.add("wrong");\n      btn.disabled = true;\n    });\n  });\n  try {\n    const data = await apiPost("/api/exams/submit", {\n      user_id: parseInt(getUserId()),\n      subject: currentQuiz.subject,\n      lesson: currentQuiz.lesson,\n      grade: currentQuiz.grade,\n      difficulty: currentQuiz.difficulty,\n      answers: userAnswers.map((a) => (a === null ? -1 : a)),\n      correct_answers: correctAnswers,\n      questions: currentQuiz.questions,\n    });\n    const resultCard = document.getElementById("result-card");\n    resultCard.style.display = "block";\n    document.getElementById("result-text").innerHTML =\n      `تعداد پاسخ صحیح: <b>${data.correct_count}</b> از ${data.total} — درصد: <b>${data.score_percent}%</b><br/>` +\n      `این نتیجه در رتبه\u200cبندی نورتیکا نیز لحاظ می\u200cشود. 🎉`;\n    renderWrongAnalysis(data.wrong_analysis);\n    resultCard.scrollIntoView({ behavior: "smooth" });\n  } catch (err) {\n    alert(err.message);\n  }\n}\nasync function submitEssayExam() {\n  const answers = currentQuiz.questions.map((q, qi) => ({\n    question: q.question,\n    student_answer: userAnswers[qi] || "",\n    model_answer: q.model_answer || "",\n  }));\n  try {\n    const data = await apiPost("/api/exams/essay/submit", {\n      user_id: parseInt(getUserId()),\n      subject: currentQuiz.subject,\n      grade: currentQuiz.grade,\n      difficulty: currentQuiz.difficulty,\n      answers,\n    });\n    const resultCard = document.getElementById("result-card");\n    resultCard.style.display = "block";\n    document.getElementById("result-text").innerHTML =\n      `میانگین درصد پاسخ\u200cهای تشریحی شما: <b>${data.average_score_percent}%</b><br/>` +\n      `تحلیل کامل هر پاسخ در پایین آمده است. 📝`;\n    renderEssayAnalysis(data.analysis);\n    resultCard.scrollIntoView({ behavior: "smooth" });\n  } catch (err) {\n    alert(err.message);\n  }\n}\nfunction renderWrongAnalysis(items) {\n  const container = document.getElementById("wrong-analysis-container");\n  if (!items || items.length === 0) {\n    container.innerHTML = `<p style="color:var(--success);font-weight:700;margin-top:12px;">🎉 همه پاسخ\u200cهای شما درست بود!</p>`;\n    return;\n  }\n  const html = items\n    .map(\n      (it, i) => `\n    <div class="card" style="margin-top:12px;border-color:#ef4444;">\n      <h4>تحلیل سوال غلط ${i + 1}</h4>\n      <p><b>سوال:</b> ${it.question}</p>\n      <p style="color:#ef4444;"><b>پاسخ شما:</b> ${it.your_answer}</p>\n      <p style="color:var(--success);"><b>پاسخ صحیح:</b> ${it.correct_answer}</p>\n      <p><b>توضیح هوش مصنوعی:</b> ${it.explanation}</p>\n    </div>`\n    )\n    .join("");\n  container.innerHTML = `<h3 style="margin-top:20px;">تحلیل سوالات غلط توسط هوش مصنوعی</h3>` + html;\n}\nfunction renderEssayAnalysis(items) {\n  const container = document.getElementById("wrong-analysis-container");\n  if (!items || items.length === 0) {\n    container.innerHTML = "";\n    return;\n  }\n  const html = items\n    .map(\n      (it, i) => `\n    <div class="card" style="margin-top:12px;">\n      <h4>سوال ${i + 1} — امتیاز: ${it.score_percent}%</h4>\n      <p><b>سوال:</b> ${it.question}</p>\n      <p><b>پاسخ شما:</b> ${it.student_answer}</p>\n      <p style="color:var(--success);"><b>پاسخ کامل و صحیح:</b> ${it.correct_answer}</p>\n      <p><b>بازخورد:</b> ${it.explanation}</p>\n    </div>`\n    )\n    .join("");\n  container.innerHTML = `<h3 style="margin-top:20px;">تحلیل پاسخ\u200cهای تشریحی</h3>` + html;\n}'
CONSULT_JS = 'document.addEventListener("DOMContentLoaded", async () => {\n  const userId = requireUser();\n  if (!userId) return;\n  try {\n    const res = await apiGet(`/api/consultation/history/${userId}`);\n    const history = document.getElementById("consult-history");\n    if (res.items && res.items.length) {\n      res.items.forEach((m) => appendConsultBubble(m.content, m.role === "user" ? "user" : "ai"));\n    } else {\n      appendConsultBubble(\n        "سلام! خوش اومدی 🌟 هر چی توی ذهنته درباره درس، رشته، امتحان یا آینده\u200cات بگو، با هم بررسیش می\u200cکنیم.",\n        "ai"\n      );\n    }\n    history.scrollTop = history.scrollHeight;\n  } catch (e) {\n    console.error(e);\n  }\n  document.getElementById("consult-send-btn").addEventListener("click", sendConsultMessage);\n  document.getElementById("consult_message").addEventListener("keydown", (e) => {\n    if (e.key === "Enter" && !e.shiftKey) {\n      e.preventDefault();\n      sendConsultMessage();\n    }\n  });\n});\nasync function sendConsultMessage() {\n  const userId = getUserId();\n  const input = document.getElementById("consult_message");\n  const alertBox = document.getElementById("consult-alert-box");\n  const message = input.value.trim();\n  if (!message) return;\n  appendConsultBubble(message, "user");\n  input.value = "";\n  alertBox.innerHTML = "";\n  const typingId = appendConsultBubble("در حال نوشتن پاسخ...", "ai", true);\n  try {\n    const data = await apiPost("/api/consultation/send", { user_id: parseInt(userId), message });\n    document.getElementById(typingId)?.remove();\n    appendConsultBubble(data.reply, "ai");\n  } catch (err) {\n    document.getElementById(typingId)?.remove();\n    alertBox.innerHTML = `<div class="alert error">${err.message}</div>`;\n  }\n}\nfunction appendConsultBubble(text, who, isTyping) {\n  const history = document.getElementById("consult-history");\n  const bubble = document.createElement("div");\n  const id = "bubble-" + Math.random().toString(36).slice(2);\n  bubble.id = id;\n  bubble.style.margin = "8px 0";\n  bubble.style.padding = "10px 14px";\n  bubble.style.borderRadius = "14px";\n  bubble.style.maxWidth = "90%";\n  bubble.style.fontSize = "0.9rem";\n  bubble.style.lineHeight = "1.7";\n  bubble.style.whiteSpace = "pre-wrap";\n  if (isTyping) bubble.style.opacity = "0.6";\n  if (who === "user") {\n    bubble.style.background = "linear-gradient(90deg, var(--primary), var(--primary-2))";\n    bubble.style.color = "#fff";\n    bubble.style.marginRight = "auto";\n    bubble.style.marginLeft = "0";\n  } else {\n    bubble.style.background = "var(--bg)";\n    bubble.style.border = "1px solid var(--card-border)";\n    bubble.style.marginLeft = "auto";\n    bubble.style.marginRight = "0";\n  }\n  bubble.textContent = text;\n  history.appendChild(bubble);\n  history.scrollTop = history.scrollHeight;\n  return id;\n}'


MAJOR_JS = 'document.addEventListener("DOMContentLoaded", () => {\n  const userId = requireUser();\n  if (!userId) return;\n  document.getElementById("ms-submit-btn").addEventListener("click", submitMajorSelection);\n});\nasync function submitMajorSelection() {\n  const btn = document.getElementById("ms-submit-btn");\n  const alertBox = document.getElementById("ms-alert-box");\n  const resultContainer = document.getElementById("ms-result-container");\n  const fullName = document.getElementById("ms_full_name").value.trim();\n  const targetField = document.getElementById("ms_target_field").value.trim();\n  const diplomaScore = document.getElementById("ms_diploma_rank").value.trim();\n  const konkurRank = document.getElementById("ms_konkur_rank").value.trim();\n  const targetCity = document.getElementById("ms_target_city").value.trim();\n  if (!fullName || !targetField || !diplomaScore || !konkurRank || !targetCity) {\n    alertBox.innerHTML = `<div class="alert error">نام، رشته مورد نظر، نمره دیپلم، رتبه کنکور و شهر مورد نظر همگی الزامی هستند.</div>`;\n    return;\n  }\n  const fd = new FormData();\n  fd.append("full_name", fullName);\n  fd.append("grade", document.getElementById("ms_grade").value);\n  fd.append("diploma_rank", diplomaScore);\n  fd.append("konkur_rank", konkurRank);\n  fd.append("target_field", targetField);\n  fd.append("target_city", targetCity);\n  const fileInput = document.getElementById("ms_file");\n  if (fileInput.files[0]) fd.append("file", fileInput.files[0]);\n  btn.disabled = true;\n  btn.textContent = "در حال جست\u200cوجو بین دانشگاه\u200cها... (ممکن است کمی طول بکشد)";\n  alertBox.innerHTML = "";\n  resultContainer.innerHTML = "";\n  try {\n    const res = await fetch("/api/major-selection/recommend", { method: "POST", body: fd });\n    if (!res.ok) {\n      const err = await res.json().catch(() => ({ detail: "خطای ناشناخته" }));\n      throw new Error(err.detail || "خطا در دریافت پیشنهاد");\n    }\n    const data = await res.json();\n    renderMajorSelectionResult(data);\n  } catch (err) {\n    alertBox.innerHTML = `<div class="alert error">${err.message}</div>`;\n  } finally {\n    btn.disabled = false;\n    btn.textContent = "پیدا کردن دانشگاه\u200cهای مناسب";\n  }\n}\nfunction renderMajorSelectionResult(data) {\n  const container = document.getElementById("ms-result-container");\n  let note = "";\n  if (data.used_pdf_search) {\n    note = `<div class="alert" style="background:rgba(124,58,237,0.1);color:var(--primary);border:1px solid rgba(124,58,237,0.3);border-radius:10px;padding:10px 14px;margin-bottom:12px;">🔎 این نتایج از داخل همون فایلی که آپلود کردی استخراج و بر اساس اطلاعاتت فیلتر شدن.</div>`;\n  } else if (!data.used_database) {\n    note = `<div class="alert" style="background:rgba(245,158,11,0.12);color:#f59e0b;border:1px solid rgba(245,158,11,0.3);border-radius:10px;padding:10px 14px;margin-bottom:12px;">⚠️ برای این ترکیب، داده کافی در بانک اطلاعاتی نورتیکا ثبت نشده؛ نتیجه زیر بر پایه تخمین هوش مصنوعی است و باید با دفترچه رسمی سازمان سنجش مقایسه شود.</div>`;\n  }\n  let tableHtml = "";\n  if (data.candidates && data.candidates.length) {\n    const rows = data.candidates\n      .map(\n        (c) => `\n      <tr>\n        <td>${c.code || "-"}</td>\n        <td>${c.university_name}</td>\n        <td>${c.major_name}</td>\n        <td>${c.city || "-"}</td>\n        <td>${c.ownership_type || "-"}</td>\n        <td>${c.min_rank || "-"} تا ${c.max_rank || "-"}</td>\n      </tr>`\n      )\n      .join("");\n    tableHtml = `\n      <div style="overflow-x:auto;margin-top:14px;">\n        <table style="width:100%;border-collapse:collapse;font-size:0.82rem;">\n          <thead>\n            <tr style="background:var(--primary);color:#fff;">\n              <th style="padding:8px;">کد</th>\n              <th style="padding:8px;">دانشگاه</th>\n              <th style="padding:8px;">رشته</th>\n              <th style="padding:8px;">شهر</th>\n              <th style="padding:8px;">نوع</th>\n              <th style="padding:8px;">بازه رتبه سال قبل</th>\n            </tr>\n          </thead>\n          <tbody>${rows}</tbody>\n        </table>\n      </div>`;\n  }\n  container.innerHTML = `\n    <div class="card">\n      <h3>نتیجه انتخاب رشته هوشمند نورتیکا</h3>\n      ${note}\n      <p style="white-space:pre-wrap;line-height:1.9;">${data.result_text}</p>\n      ${tableHtml}\n      <div style="margin-top:14px;display:flex;gap:10px;flex-wrap:wrap;">\n        <a href="/api/major-selection/pdf/${data.request_id}" target="_blank" class="btn secondary" style="display:inline-block;">دانلود نسخه PDF</a>\n        <button type="button" id="ms-download-txt-btn" class="btn secondary">دانلود نسخه متنی (TXT)</button>\n      </div>\n    </div>\n  `;\n  const txtBtn = document.getElementById("ms-download-txt-btn");\n  if (txtBtn) {\n    txtBtn.addEventListener("click", () => {\n      let txt = "نتیجه انتخاب رشته هوشمند نورتیکا\n" + data.result_text + "\n";\n      if (data.candidates && data.candidates.length) {\n        txt += "\nفهرست کدرشته\u200cهای پیشنهادی:\n";\n        data.candidates.forEach((c) => {\n          txt += `- کد ${c.code || "-"} | ${c.university_name} | ${c.major_name} | شهر ${c.city || "-"} | نوع ${c.ownership_type || "-"} | بازه رتبه ${c.min_rank || "-"} تا ${c.max_rank || "-"}\n`;\n        });\n      }\n      const blob = new Blob([txt], { type: "text/plain;charset=utf-8" });\n      const url = URL.createObjectURL(blob);\n      const a = document.createElement("a");\n      a.href = url;\n      a.download = "noortika-major-selection.txt";\n      document.body.appendChild(a);\n      a.click();\n      document.body.removeChild(a);\n      URL.revokeObjectURL(url);\n    });\n  }\n  container.scrollIntoView({ behavior: "smooth", block: "start" });\n}'


BG3D_JS = '(function () {\n  function initNoortikaBg3D() {\n    const canvas = document.getElementById("bg3d-canvas");\n    if (!canvas || typeof THREE === "undefined") return;\n    const scene = new THREE.Scene();\n    const camera = new THREE.PerspectiveCamera(\n      60,\n      window.innerWidth / window.innerHeight,\n      0.1,\n      1000\n    );\n    camera.position.z = 42;\n    const renderer = new THREE.WebGLRenderer({\n      canvas: canvas,\n      alpha: true,\n      antialias: true,\n    });\n    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));\n    renderer.setSize(window.innerWidth, window.innerHeight);\n    renderer.setClearColor(0x000000, 0);\n    // ---------- ابرِ ذرات درخشان (Particles) ----------\n    const particleCount = window.innerWidth < 640 ? 120 : 260;\n    const positions = new Float32Array(particleCount * 3);\n    const colors = new Float32Array(particleCount * 3);\n    const brandColors = [\n      new THREE.Color(0x7c3aed),\n      new THREE.Color(0xec4899),\n      new THREE.Color(0xf59e0b),\n      new THREE.Color(0xa78bfa),\n    ];\n    for (let i = 0; i < particleCount; i++) {\n      positions[i * 3] = (Math.random() - 0.5) * 90;\n      positions[i * 3 + 1] = (Math.random() - 0.5) * 60;\n      positions[i * 3 + 2] = (Math.random() - 0.5) * 60;\n      const c = brandColors[Math.floor(Math.random() * brandColors.length)];\n      colors[i * 3] = c.r;\n      colors[i * 3 + 1] = c.g;\n      colors[i * 3 + 2] = c.b;\n    }\n    const particleGeometry = new THREE.BufferGeometry();\n    particleGeometry.setAttribute("position", new THREE.BufferAttribute(positions, 3));\n    particleGeometry.setAttribute("color", new THREE.BufferAttribute(colors, 3));\n    const particleMaterial = new THREE.PointsMaterial({\n      size: 0.6,\n      vertexColors: true,\n      transparent: true,\n      opacity: 0.85,\n      blending: THREE.AdditiveBlending,\n      depthWrite: false,\n    });\n    const particles = new THREE.Points(particleGeometry, particleMaterial);\n    scene.add(particles);\n    // ---------- چندضلعی\u200cهای شناور (Wireframe Icosahedrons) ----------\n    const shapes = [];\n    const shapeColors = [0x7c3aed, 0xec4899, 0xf59e0b];\n    const shapeCount = window.innerWidth < 640 ? 2 : 4;\n    for (let i = 0; i < shapeCount; i++) {\n      const geo = new THREE.IcosahedronGeometry(3 + Math.random() * 2.5, 0);\n      const mat = new THREE.MeshBasicMaterial({\n        color: shapeColors[i % shapeColors.length],\n        wireframe: true,\n        transparent: true,\n        opacity: 0.5,\n      });\n      const mesh = new THREE.Mesh(geo, mat);\n      mesh.position.set(\n        (Math.random() - 0.5) * 60,\n        (Math.random() - 0.5) * 34,\n        (Math.random() - 0.5) * 30 - 10\n      );\n      mesh.userData = {\n        speed: 0.002 + Math.random() * 0.004,\n        floatSpeed: 0.4 + Math.random() * 0.6,\n        floatOffset: Math.random() * Math.PI * 2,\n        baseY: mesh.position.y,\n      };\n      scene.add(mesh);\n      shapes.push(mesh);\n    }\n    // ---------- لوگوی شناور نورتیکا در پس\u200cزمینه ----------\n    const logoTexture = new THREE.TextureLoader().load("/logo.jpg");\n    const logoGeo = new THREE.CircleGeometry(6, 48);\n    const logoMat = new THREE.MeshBasicMaterial({\n      map: logoTexture,\n      transparent: true,\n      opacity: 0.18,\n      depthWrite: false,\n    });\n    const logoMesh = new THREE.Mesh(logoGeo, logoMat);\n    logoMesh.position.set(16, 8, -20);\n    scene.add(logoMesh);\n    const logoMesh2 = new THREE.Mesh(logoGeo.clone(), logoMat.clone());\n    logoMesh2.scale.set(0.6, 0.6, 0.6);\n    logoMesh2.position.set(-18, -10, -25);\n    scene.add(logoMesh2);\n    window.addEventListener("resize", () => {\n      camera.aspect = window.innerWidth / window.innerHeight;\n      camera.updateProjectionMatrix();\n      renderer.setSize(window.innerWidth, window.innerHeight);\n    });\n    const clock = new THREE.Clock();\n    function animate() {\n      requestAnimationFrame(animate);\n      const t = clock.getElapsedTime();\n      particles.rotation.y = t * 0.02;\n      particles.rotation.x = t * 0.01;\n      shapes.forEach((mesh) => {\n        mesh.rotation.x += mesh.userData.speed;\n        mesh.rotation.y += mesh.userData.speed * 1.3;\n        mesh.position.y =\n          mesh.userData.baseY + Math.sin(t * mesh.userData.floatSpeed + mesh.userData.floatOffset) * 1.5;\n      });\n      logoMesh.rotation.z = t * 0.05;\n      logoMesh2.rotation.z = -t * 0.04;\n      logoMesh.position.y = 8 + Math.sin(t * 0.3) * 2;\n      logoMesh2.position.y = -10 + Math.sin(t * 0.25 + 2) * 2;\n      renderer.render(scene, camera);\n    }\n    animate();\n  }\n  if (document.readyState === "loading") {\n    document.addEventListener("DOMContentLoaded", initNoortikaBg3D);\n  } else {\n    initNoortikaBg3D();\n  }\n})();'

